function ensure_member_soft_delete_schema(PDO $p):void{static$d=false;if($d)return;$db=(string)$p->query('SELECT DATABASE()')->fetchColumn();$s=$p->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=:db AND TABLE_NAME="members" AND COLUMN_NAME IN ("deleted_at","deleted_by_admin_id")');$s->execute(['db'=>$db]);$c=array_column($s->fetchAll(),'COLUMN_NAME');if(!in_array('deleted_at',$c,true))$p->exec('ALTER TABLE members ADD COLUMN deleted_at DATETIME NULL AFTER notes, ADD INDEX idx_members_deleted_at (deleted_at)');if(!in_array('deleted_by_admin_id',$c,true))$p->exec('ALTER TABLE members ADD COLUMN deleted_by_admin_id INT UNSIGNED NULL AFTER deleted_at');$d=true;}
function ensure_member_type_schema(PDO $p):void{static$d=false;if($d)return;$db=(string)$p->query('SELECT DATABASE()')->fetchColumn();$s=$p->prepare('SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=:db AND TABLE_NAME="members" AND COLUMN_NAME="member_type"');$s->execute(['db'=>$db]);$t=(string)$s->fetchColumn();if($t!==''&&!str_contains($t,"'pilot'")){$p->exec("ALTER TABLE members MODIFY member_type ENUM('supporting','flying','viewer','flyer','pilot') NOT NULL DEFAULT 'viewer'");$p->exec("UPDATE members SET member_type='viewer' WHERE member_type='supporting'");$p->exec("UPDATE members SET member_type='flyer' WHERE member_type='flying'");$p->exec("ALTER TABLE members MODIFY member_type ENUM('viewer','flyer','pilot') NOT NULL DEFAULT 'viewer'");}$s=$p->prepare('SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=:db AND TABLE_NAME="memberships" AND COLUMN_NAME="membership_type"');$s->execute(['db'=>$db]);$t=(string)$s->fetchColumn();if($t!==''&&!str_contains($t,"'pilot'")){$p->exec("ALTER TABLE memberships MODIFY membership_type ENUM('supporting','flying','viewer','flyer','pilot') NOT NULL");$p->exec("UPDATE memberships SET membership_type='viewer' WHERE membership_type='supporting'");$p->exec("UPDATE memberships SET membership_type='flyer' WHERE membership_type='flying'");$p->exec("ALTER TABLE memberships MODIFY membership_type ENUM('viewer','flyer','pilot') NOT NULL");}$p->exec("UPDATE memberships ms INNER JOIN members m ON m.id=ms.member_id SET ms.free_flight_entitled=CASE WHEN m.member_type='flyer' THEN 1 ELSE 0 END");$d=true;}
